def _is_ollama_rate_or_quota_error(exc: BaseException) -> bool:
    """Detect HTTP 429 / rate or quota signals from Ollama (incl. wrapped causes)."""
    try:
        import httpx
    except ImportError:
        httpx = None  # type: ignore[assignment]

    seen: set[int] = set()
    stack: list[BaseException] = [exc]
    while stack:
        err = stack.pop()
        eid = id(err)
        if eid in seen:
            continue
        seen.add(eid)
        if httpx is not None and isinstance(err, httpx.HTTPStatusError):
            if err.response.status_code == 429:
                return True
        low = str(err).lower()
        if "429" in low or "too many requests" in low or "resource exhausted" in low:
            return True
        if err.__cause__ is not None:
            stack.append(err.__cause__)
        ctx = err.__context__
        if ctx is not None and ctx is not err.__cause__:
            stack.append(ctx)
    return False

